('a4723c19-a80b-49bb-bb02-6c5cdded3c95','MA','a08080a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Insider Morocco SARL','Insider Morocco','guided_experience',3,'verified',ARRAY['en','fr','ar'],'Boutique guiding company pairing you with a dedicated guide for a personalized half-day or full-day experience. We adapt the route to your interests on the fly.',1.6,92.5,443,4.5,'active'),
('9bf8272f-827b-4ad2-b34c-e3009077b984','MA','a08080a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Kasbah Storytellers SARL','Kasbah Storytellers','guided_experience',2,'verified',ARRAY['en','fr','ary-Latn'],'Cultural preservation association. Our guides are retired teachers and historians who share oral traditions, folklore, and stories passed down for generations.',2.2,89.6,82,4.5,'active'),
('b7fd5cf9-2133-4810-b168-83b7320edef7','MA','a08080a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Dar Ourika Valley Cooking School SARL','Dar Ourika Valley Cooking School','workshop',2,'verified',ARRAY['en','fr','ary-Latn'],'A traditional riad kitchen where a local family teaches you to prepare tagine, couscous, and pastries from scratch. Small classes, maximum 6 people.',10.9,92.8,88,4,'active'),
('c0cab024-8245-4b27-9011-a96dc6736e4c','MA','a08080a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Maison des Artisans SARL','Maison des Artisans','workshop',2,'verified',ARRAY['en','fr','ar'],'A cooperative workshop space where master artisans — potters, leatherworkers, zellige cutters — teach their craft in 2-hour hands-on sessions. Materials included.',4.5,92.4,376,4.4,'active'),
('66dacb64-db40-41dc-903b-003ba759ce51','MA','a08080a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Atelier Lumière SARL','Atelier Lumière','workshop',4,'verified',ARRAY['en','fr','es'],'A luxury creative studio offering private masterclasses with acclaimed Moroccan artists. Photography, calligraphy, and perfume-making in a beautifully restored medina house.',8.4,89.7,436,3.9,'active'),
('3ff5defc-89f8-48e3-90b0-454998398dab','MA','a08080a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Riad Ourika Valley Budget SARL','Riad Ourika Valley Budget','stay',1,'verified',ARRAY['en','fr'],'A clean, friendly guesthouse in the heart of the medina. Shared bathrooms, rooftop terrace, and free mint tea. Perfect for backpackers and solo travelers.',10.7,98.1,261,4.2,'active'),
('c880d252-7130-4fba-9083-a370a2521bf5','MA','a08080a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Dar Ourika Valley Boutique SARL','Dar Ourika Valley Boutique','stay',3,'verified',ARRAY['en','fr','es'],'A beautifully restored 19th-century riad with 8 rooms, each uniquely decorated with antiques and local textiles. Plunge pool, hammam, and breakfast on the rooftop.',3.6,89.1,352,3.9,'active'),
('383a13ea-bbd6-4454-a9e6-31bb569d10cb','MA','a08080a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Palais Ourika Valley Royal SARL','Palais Ourika Valley Royal','stay',4,'verified',ARRAY['en','fr','it','de'],'A former palace converted into an all-suite luxury hotel. Private butlers, Michelin-trained chef, spa, and curated excursions. The finest address in the city.',7.5,91.3,422,3.5,'active'),
('2a93c968-3dc8-4150-a2c9-d4b544c94eaa','MA','a08080a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Street Food Ourika Valley Tours SARL','Street Food Ourika Valley Tours','meal',1,'verified',ARRAY['en','fr','ary-Latn'],'We take you through the best food stalls and hidden corners of the medina. 6+ tastings, from bissara to snail soup. Come hungry!',4.8,97.6,170,3.8,'active'),
('4fd9881b-ee4a-4a5d-83b5-a795405354fa','MA','a08080a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Table Ourika Valley Family Kitchen SARL','Table Ourika Valley Family Kitchen','meal',2,'verified',ARRAY['en','fr','ary-Latn'],'A Moroccan family welcomes you into their home for a traditional 3-course dinner. Couscous on Fridays, tagine every day. Recipes passed down four generations.',11.4,89.3,106,4.4,'active'),
('03848298-8fdb-4f29-8211-c0986f7148a0','MA','a08080a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Le Salon Ourika Valley SARL','Le Salon Ourika Valley','meal',4,'verified',ARRAY['en','fr'],'Fine dining in an elegant riad setting. Modern Moroccan cuisine by a chef trained in Paris and Marrakech. Wine pairing available. Reservation required.',2.7,90.4,42,3.7,'active'),
('3925d154-b07d-43d7-aa40-8a1c0e9dbde7','MA','a08080a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Ourika Valley Adventure Club SARL','Ourika Valley Adventure Club','activity',2,'verified',ARRAY['en','fr','ar'],'A local outdoor club offering hiking, cycling, and climbing for all levels. Certified guides, quality equipment, and a passion for sharing Morocco''s natural beauty.',3.4,93.2,98,4.9,'active'),
